set -euo pipefail
cd /home/ubuntu/apps/travel-planner
.venv/bin/python - <<'PY'
from pathlib import Path
import base64,json,hashlib,shutil
payload=json.loads('{"rag/eval/candidates/answer_evidence_v2/manifest.json": "", "rag/eval/candidates/plan_v1/manifest.json": "", "rag/eval/reports/luoyang_one_day_v1_final.md": ""}')
for n,b in payload.items():
 p=Path(n); p.parent.mkdir(parents=True,exist_ok=True); p.write_bytes(base64.b64decode(b))
root=Path('rag/eval/baselines/answer_evidence_v2')
m=json.loads((root/'manifest.json').read_text())
for n,h in m['files'].items(): assert hashlib.sha256((root/n).read_bytes()).hexdigest()==h,n
for n,h in json.loads(Path('rag/eval/candidates/plan_v1/manifest.json').read_text())['file_sha256'].items(): assert hashlib.sha256(Path(n).read_bytes()).hexdigest()==h,n
for src,dst in [('luoyang_one_day_v1_final.md','plan-evaluation-9-2026-10-13.md'),('planning_v1_qa_regression.json','planning_v1_qa_regression.json')]:
 p=Path('/home/ubuntu/portfolio/downloads/rag')/dst; shutil.copyfile(Path('rag/eval/reports')/src,p); p.chmod(0o644)
print('Remote baseline, candidate evidence, and publication verified')
PY
for name in plan-evaluation-9-2026-10-13.md planning_v1_qa_regression.json; do
  disk=$(sha256sum "/home/ubuntu/portfolio/downloads/rag/$name" | cut -d ' ' -f1)
  http=$(curl -fsS "http://52.199.126.245/downloads/rag/$name" | sha256sum | cut -d ' ' -f1)
  test "$disk" = "$http"
  printf '%s %s HTTP_SHA256_MATCH\n' "$name" "$disk"
done
